import html, re

def clean(text):
    text = re.sub(r'<[^>]+>', ' ', text or '')
    return re.sub(r'\s+', ' ', html.unescape(text)).strip()

def main(input):
    jobs = input['data'].get('jobs', [])
    picked = [
        {'title': j['title'], 'company': j.get('company_name'), 'url': j['url'],
         'location': j.get('candidate_required_location'), 'description': clean(j.get('description'))[:1500]}
        for j in jobs[: args['max_jobs']]
    ]
    print(f'kept {len(picked)} of {len(jobs)} jobs')
    return {'jobs': picked}

def main(input):
    r = input['result']
    lines = [r['summary'], '']
    for m in sorted(r['matches'], key=lambda m: -m['score']):
        lines.append(f"{m['score']:>3}/100  {m['title']} @ {m['company']}")
        lines.append(f"         {m['url']}")
        if m['strengths']:
            lines.append('         + ' + '; '.join(m['strengths']))
        if m['gaps']:
            lines.append('         - ' + '; '.join(m['gaps']))
        lines.append('')
    subject = f"{len(r['matches'])} job matches - best fit {r['best_score']}/100"
    return {'subject': subject, 'body': '\n'.join(lines)}
